using Microsoft.EntityFrameworkCore;
using OnlineLearningApp.Data;
using OnlineLearningApp.Models;

namespace OnlineLearningApp;

public class CourseService : EntityBaseRepository<Course>, ICourseService
{
    private readonly OnlineLearningAppDbContext _context;
    public CourseService(OnlineLearningAppDbContext context):base(context)=>_context=context;
    public async Task AddNewCourseAsync(NewCourseViewModel data){var c=new Course{CourseName=data.CourseName.Trim(),Description=data.Description.Trim(),Price=data.Price,ImageURL=data.ImageURL.Trim(),Category=data.Category,StartDate=data.StartDate,EndDate=data.EndDate,Status=data.Status,InstructorId=data.InstructorId,RequireAllQuizzesPassed=data.RequireAllQuizzesPassed,RequirePaymentForAssessment=data.RequirePaymentForAssessment,RequireCapstone=data.RequireCapstone,CapstoneTitle=data.CapstoneTitle.Trim(),CapstoneDescription=data.CapstoneDescription.Trim(),CapstoneRequirements=data.CapstoneRequirements.Trim()};await _context.Courses.AddAsync(c);await _context.SaveChangesAsync();c.CourseId=c.Id;var ids=data.ModuleIds.Distinct().ToList();if(ids.Count>0){var valid=await _context.Modules.Where(m=>ids.Contains(m.ModuleId)).Select(m=>m.ModuleId).ToListAsync();foreach(var id in valid)_context.Courses_Modules.Add(new Course_Module{CourseId=c.Id,ModuleId=id});}await _context.SaveChangesAsync();}
    public async Task<Course?> GetCourseByIdAsync(int id)=>await _context.Courses.AsNoTracking().Include(c=>c.Instructor).Include(c=>c.Courses_Modules).ThenInclude(cm=>cm.Module).FirstOrDefaultAsync(c=>c.Id==id);
    public async Task<NewCourseDropdownViewModel> GetNewCourseDropdownsValues(){var roleId=await _context.Roles.Where(r=>r.Name==UserRoles.Instructor).Select(r=>r.Id).FirstOrDefaultAsync();var instructors=await _context.Accounts.Where(a=>roleId!=null&&_context.UserRoles.Any(ur=>ur.UserId==a.Id&&ur.RoleId==roleId)).OrderBy(a=>a.FullName).Select(a=>new User{UserId=a.Id,FullName=a.FullName}).ToListAsync();return new NewCourseDropdownViewModel{Instructors=instructors,Categories=Enum.GetValues<CourseCategory>().OrderBy(c=>c).ToList()};}
    public async Task UpdateCourseAsync(NewCourseViewModel data){var c=await _context.Courses.FirstOrDefaultAsync(x=>x.Id==data.Id)??throw new KeyNotFoundException($"Course with id {data.Id} was not found.");c.CourseName=data.CourseName.Trim();c.Description=data.Description.Trim();c.Price=data.Price;c.ImageURL=data.ImageURL.Trim();c.Category=data.Category;c.StartDate=data.StartDate;c.EndDate=data.EndDate;c.Status=data.Status;c.InstructorId=data.InstructorId;c.RequireAllQuizzesPassed=data.RequireAllQuizzesPassed;c.RequirePaymentForAssessment=data.RequirePaymentForAssessment;c.RequireCapstone=data.RequireCapstone;c.CapstoneTitle=data.CapstoneTitle.Trim();c.CapstoneDescription=data.CapstoneDescription.Trim();c.CapstoneRequirements=data.CapstoneRequirements.Trim();c.CourseId=c.Id;var existing=await _context.Courses_Modules.Where(cm=>cm.CourseId==data.Id).ToListAsync();_context.Courses_Modules.RemoveRange(existing);var ids=data.ModuleIds.Distinct().ToList();if(ids.Count>0){var valid=await _context.Modules.Where(m=>ids.Contains(m.ModuleId)).Select(m=>m.ModuleId).ToListAsync();foreach(var id in valid)_context.Courses_Modules.Add(new Course_Module{CourseId=data.Id,ModuleId=id});}await _context.SaveChangesAsync();}
}
